import calendar


def _parse_field(field, min_val, max_val):
    values = set()
    for part in field.split(','):
        if part == '*':
            values.update(range(min_val, max_val + 1))
        elif '/' in part:
            left, step = part.split('/')
            step = int(step)
            if '-' in left:
                start, end = left.split('-')
                values.update(range(int(start), int(end) + 1, step))
            else:
                start = min_val if left == '*' else int(left)
                values.update(range(start, max_val + 1, step))
        elif '-' in part:
            start, end = part.split('-')
            values.update(range(int(start), int(end) + 1))
        else:
            values.add(int(part))
    return values


def _is_restricted(field):
    return field.strip() != '*'


def next_fire(cron_expr, after_iso):
