        else:
            day_matches = (dt.day in doms and dt.day <= max_day) and (cron_weekday in dows)

        if not day_matches:
            dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if dt.hour not in hours:
            next_hour = next((h for h in sorted(hours) if h > dt.hour), None)
