            if next_minute is None:
                dt = (dt + timedelta(hours=1)).replace(minute=0)
            else:
                dt = dt.replace(minute=next_minute)
            continue

        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    raise ValueError("No matching timestamp found within search limit")
