from datetime import datetime, timezone, timedelta
import calendar

def _parse_field(field, min_val, max_val):
    result = set()
    for part in field.split(','):
        if '/' in part:
            range_part, step = part.split('/', 1)
            step = int(step)
            if range_part == '*':
                start, end = min_val, max_val
            elif '-' in range_part:
                start, end = map(int, range_part.split('-', 1))
            else:
                start = int(range_part)
                end = max_val
            for v in range(start, end + 1, step):
                result.add(v)
        elif '-' in part:
            start, end = map(int, part.split('-', 1))
            for v in range(start, end + 1):
                result.add(v)
        elif part == '*':
            for v in range(min_val, max_val + 1):
                result.add(v)
        else:
            result.add(int(part))
    return result

def next_fire(cron_expr, after_iso):
    fields = cron_expr.split()
    minute_f, hour_f, dom_f, month_f, dow_f = fields

    minutes = _parse_field(minute_f, 0, 59)
    hours = _parse_field(hour_f, 0, 23)
    doms = _parse_field(dom_f, 1, 31)
    months = _parse_field(month_f, 1, 12)
    dows = _parse_field(dow_f, 0, 6)

    dom_restricted = dom_f != '*'
    dow_restricted = dow_f != '*'

    dt = datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    dt = dt + timedelta(minutes=1)
    dt = dt.replace(second=0, microsecond=0)

    max_iterations = 527040 * 5

    for _ in range(max_iterations):
        if dt.month not in months:
            month = dt.month
            year = dt.year
            while True:
                month += 1
                if month > 12:
                    month = 1
                    year += 1
                if month in months:
                    break
            dt = dt.replace(year=year, month=month, day=1, hour=0, minute=0)
            continue

        py_dow = dt.weekday()  # 0=Mon..6=Sun
        cron_dow = (py_dow + 1) % 7  # 0=Sun,1=Mon,...,6=Sat

        max_day = calendar.monthrange(dt.year, dt.month)[1]
        dom_match = dt.day in doms and dt.day <= max_day
        dow_match = cron_dow in dows

        if dom_restricted and dow_restricted:
            day_ok = dom_match or dow_match
        else:
            day_ok = dom_match and dow_match

        if not day_ok:
            next_day = dt + timedelta(days=1)
            dt = next_day.replace(hour=0, minute=0)
            continue

        if dt.hour not in hours:
            hour = dt.hour
            found = False
            for h in sorted(hours):
                if h > hour:
                    dt = dt.replace(hour=h, minute=0)
                    found = True
                    break
            if not found:
                next_day = dt + timedelta(days=1)
                dt = next_day.replace(hour=0, minute=0)
            continue

        if dt.minute not in minutes:
            minute = dt.minute
            found = False
            for m in sorted(minutes):
                if m > minute:
                    dt = dt.replace(minute=m)
                    found = True
                    break
            if not found:
                dt = dt + timedelta(hours=1)
                dt = dt.replace(minute=0)
            continue

        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    raise ValueError("No matching timestamp found within search range")
