def render_table(rows, widths, aligns):
    border = _make_border(widths)

    if not rows:
        return border + '\n' + border

    lines = [border]
    for row in rows:
        visual_lines = _render_row(row, widths, aligns)
        lines.extend(visual_lines)
        lines.append(border)

    return '\n'.join(lines)


def _make_border(widths):
    parts = ['+']
    for w in widths:
        parts.append('-' * (w + 2))
        parts.append('+')
    return ''.join(parts)


def _wrap_cell(text, width):
    if not text:
        return ['']

    words = text.split(' ')
    words = [w for w in words if w != '']

    if not words:
        return ['']

    visual_lines = []
    current_line = ''

    for word in words:
        if len(word) > width:
            if current_line:
                visual_lines.append(current_line)
                current_line = ''
            pos = 0
            while pos < len(word):
                chunk = word[pos:pos + width]
                visual_lines.append(chunk)
                pos += width
        else:
            if current_line == '':
                current_line = word
            elif len(current_line) + 1 + len(word) <= width:
                current_line = current_line + ' ' + word
            else:
                visual_lines.append(current_line)
                current_line = word

    if current_line or not visual_lines:
        visual_lines.append(current_line)

    return visual_lines


def _truncate_cell(visual_lines, width):
    max_lines = 3
    if len(visual_lines) <= max_lines:
        return visual_lines

    kept = visual_lines[:max_lines]
    third = kept[2]

    if width >= 3:
        kept[2] = third[:width - 3] + '...'
    else:
        kept[2] = '.' * width

    return kept


def _align_text(text, width, align):
    extra = width - len(text)
    if align == 'l':
        return text + ' ' * extra
    elif align == 'r':
        return ' ' * extra + text
    elif align == 'c':
        left_pad = extra // 2
        right_pad = extra - left_pad
        return ' ' * left_pad + text + ' ' * right_pad
    return text


def _render_row(row, widths, aligns):
    cell_lines = []
    for i, cell in enumerate(row):
        wrapped = _wrap_cell(cell, widths[i])
        truncated = _truncate_cell(wrapped, widths[i])
        cell_lines.append(truncated)

    row_height = max(len(cl) for cl in cell_lines)

    visual_rows = []
    for line_idx in range(row_height):
        parts = ['|']
        for col_idx, cl in enumerate(cell_lines):
            if line_idx < len(cl):
                text = cl[line_idx]
            else:
                text = ''
            aligned = _align_text(text, widths[col_idx], aligns[col_idx])
            parts.append(' ')
            parts.append(aligned)
            parts.append(' |')
        visual_rows.append(''.join(parts))

    return visual_rows
