            truncated = _truncate(wrapped, w)
            cell_lines_list.append(truncated)

        row_height = max(len(cl) for cl in cell_lines_list)

        for visual_line_idx in range(row_height):
            line = '|'
            for col_idx in range(len(widths)):
                w = widths[col_idx]
                a = aligns[col_idx]
                cl = cell_lines_list[col_idx]
                text = cl[visual_line_idx] if visual_line_idx < len(cl) else ''
                line += ' ' + _align(text, w, a) + ' |'
            all_lines.append(line)

        all_lines.append(border)

    return '\n'.join(all_lines)
