def render_table(rows, widths, aligns):
    def _make_border(widths):
        return '+' + ''.join('-' * (w + 2) + '+' for w in widths)

    def _wrap_cell(text, width):
        if not text:
            return ['']
        words = [w for w in text.split(' ') if w != '']
        if not words:
            return ['']
        lines = []
        current_line = ''
        for word in words:
            if len(word) > width:
                if current_line:
                    lines.append(current_line)
                    current_line = ''
                for i in range(0, len(word), width):
                    lines.append(word[i:i + width])
            else:
                if current_line == '':
                    current_line = word
                elif len(current_line) + 1 + len(word) <= width:
                    current_line = current_line + ' ' + word
                else:
                    lines.append(current_line)
                    current_line = word
        if current_line != '':
            lines.append(current_line)
        return lines if lines else ['']

    def _truncate_cell(lines, width, max_lines=3):
        if len(lines) <= max_lines:
            return lines
        kept = list(lines[:max_lines])
        if width >= 3:
            kept[2] = kept[2][:width - 3] + '...'
        else:
            kept[2] = '.' * width
        return kept

    def _align_text(text, width, align):
        extra = width - len(text)
        if extra <= 0:
            return text[:width]
        if align == 'l':
            return text + ' ' * extra
        elif align == 'r':
            return ' ' * extra + text
        else:  # 'c'
            left_pad = extra // 2
            right_pad = extra - left_pad
            return ' ' * left_pad + text + ' ' * right_pad

    border = _make_border(widths)

    if not rows:
        return border + '\n' + border

    result_lines = [border]

    for row in rows:
        cell_visual_lines = []
        for col_idx, cell in enumerate(row):
            w = widths[col_idx]
            wrapped = _wrap_cell(cell, w)
            truncated = _truncate_cell(wrapped, w)
            cell_visual_lines.append(truncated)

        row_height = max(len(lines) for lines in cell_visual_lines)

        for line_idx in range(row_height):
            parts = ['|']
            for col_idx in range(len(widths)):
                w = widths[col_idx]
                a = aligns[col_idx]
                cell_lines = cell_visual_lines[col_idx]
                text = cell_lines[line_idx] if line_idx < len(cell_lines) else ''
                aligned = _align_text(text, w, a)
                parts.append(' ')
                parts.append(aligned)
                parts.append(' |')
            result_lines.append(''.join(parts))

        result_lines.append(border)

    return '\n'.join(result_lines)
