from bisect import bisect_right


def weighted_interval_schedule(intervals):
    if not intervals:
        return (0, [])

    # Sort by (end, start, id) — matches required output ordering
    sorted_ivs = sorted(intervals, key=lambda x: (x[2], x[1], x[0]))
    n = len(sorted_ivs)
    end_times = [iv[2] for iv in sorted_ivs]

    def last_compatible(j):
        # Half-open semantics: compatible iff end <= start (touching is ok)
        return bisect_right(end_times, sorted_ivs[j][1]) - 1

    # Solution: (weight, count, start_list, id_list)
    EMPTY = (0, 0, [], [])

    def combine(sol, iv):
        w, cnt, sl, il = sol
        iid, istart, _end, iw = iv
        return (w + iw, cnt + 1, sl + [istart], il + [iid])

    def better(a, b):
        if a[0] != b[0]:
            return a[0] > b[0]
        if a[1] != b[1]:
            return a[1] < b[1]
        if a[2] != b[2]:
            return a[2] < b[2]
        return a[3] < b[3]

    OPT = [None] * (n + 1)
    OPT[0] = EMPTY

    for j in range(n):
        p = last_compatible(j)
        with_j = combine(OPT[p + 1], sorted_ivs[j])
        without_j = OPT[j]
        OPT[j + 1] = with_j if better(with_j, without_j) else without_j

    weight, _cnt, _sl, id_list = OPT[n]
    return (weight, id_list)
