import bisect


def weighted_interval_schedule(intervals):
    if not intervals:
        return (0, [])

    # Do not mutate input; work on a sorted copy
    sorted_intervals = sorted(intervals, key=lambda x: (x[2], x[1], x[0]))
    n = len(sorted_intervals)

    ends = [iv[2] for iv in sorted_intervals]

    def find_compatible(j):
        # Rightmost index whose end <= start of j (half-open: touching is compatible)
        start_j = sorted_intervals[j][1]
        return bisect.bisect_right(ends, start_j) - 1

    def schedule_key(weight, chosen_indices):
        starts = tuple(sorted_intervals[i][1] for i in chosen_indices)
        ids = tuple(sorted_intervals[i][0] for i in chosen_indices)
        return (-weight, len(chosen_indices), starts, ids)

    def is_better(w1, c1, w2, c2):
        return schedule_key(w1, c1) < schedule_key(w2, c2)

    empty_weight = 0
    empty_chosen = ()

    prefix_w = [0] * n
    prefix_c = [None] * n

    for j in range(n):
        w_j = sorted_intervals[j][3]

        p = find_compatible(j)
        if p < 0:
            cand_w = empty_weight + w_j
            cand_c = empty_chosen + (j,)
        else:
            cand_w = prefix_w[p] + w_j
            cand_c = prefix_c[p] + (j,)

        if j == 0:
            prev_w, prev_c = empty_weight, empty_chosen
        else:
            prev_w, prev_c = prefix_w[j - 1], prefix_c[j - 1]

        if is_better(cand_w, cand_c, prev_w, prev_c):
            prefix_w[j], prefix_c[j] = cand_w, cand_c
        else:
            prefix_w[j], prefix_c[j] = prev_w, prev_c

    best_weight = prefix_w[n - 1]
    best_chosen = prefix_c[n - 1]

    if not best_chosen:
        return (0, [])

    chosen_ids = [sorted_intervals[i][0] for i in best_chosen]
    return (best_weight, chosen_ids)
