import bisect


def weighted_interval_schedule(intervals):
    if not intervals:
        return (0, [])

    sorted_ivs = sorted(intervals, key=lambda x: (x[2], x[1], x[0]))
    n = len(sorted_ivs)
    ends = [iv[2] for iv in sorted_ivs]

    def last_compatible(i):
        target = sorted_ivs[i][1]
        pos = bisect.bisect_right(ends, target) - 1
        if pos >= i:
            pos = i - 1
        return pos

    def schedule_key(weight, chosen):
        return (-weight, len(chosen), [iv[1] for iv in chosen], [iv[0] for iv in chosen])

    def is_better(w1, c1, w2, c2):
        return schedule_key(w1, c1) < schedule_key(w2, c2)

    best_up_to = [None] * n

    for i in range(n):
        iv = sorted_ivs[i]
        w, chosen = iv[3], [iv]

        j = last_compatible(i)
        if j >= 0:
            prev_w, prev_chosen = best_up_to[j]
            cw, cc = prev_w + iv[3], prev_chosen + [iv]
            if is_better(cw, cc, w, chosen):
                w, chosen = cw, cc

        if i == 0:
            best_up_to[i] = (w, chosen)
        else:
            prev_w, prev_chosen = best_up_to[i - 1]
            if is_better(w, chosen, prev_w, prev_chosen):
                best_up_to[i] = (w, chosen)
            else:
                best_up_to[i] = best_up_to[i - 1]

    final_w, final_chosen = best_up_to[n - 1]

    if is_better(0, [], final_w, final_chosen):
        return (0, [])

    return (final_w, [iv[0] for iv in final_chosen])
