    for part in field.split(','):
        if part == '*':
            result.update(range(min_val, max_val + 1))
        elif '/' in part:
            base, step = part.split('/')
            step = int(step)
            if '-' in base:
                start, end = map(int, base.split('-'))
            elif base == '*':
                start, end = min_val, max_val
            else:
                start, end = int(base), max_val
            result.update(range(start, end + 1, step))
        elif '-' in part:
            start, end = map(int, part.split('-'))
            result.update(range(start, end + 1))
        else:
            result.add(int(part))
    return result


def next_fire(cron_expr: str, after_iso: str) -> str:
    minute_f, hour_f, dom_f, month_f, dow_f = cron_expr.split()

    minutes = _parse_field(minute_f, 0, 59)
    hours = _parse_field(hour_f, 0, 23)
    doms = _parse_field(dom_f, 1, 31)
    months = _parse_field(month_f, 1, 12)
    dows = _parse_field(dow_f, 0, 6)

    dom_restricted = dom_f != '*'
    dow_restricted = dow_f != '*'

    dt = datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    dt = (dt + timedelta(minutes=1)).replace(second=0, microsecond=0)

    for _ in range(366 * 24 * 60 * 5):
        # Advance to next valid month
        if dt.month not in months:
            m, y = dt.month, dt.year
            for _ in range(25):
                m += 1
                if m > 12:
                    m, y = 1, y + 1
                if m in months:
                    dt = datetime(y, m, 1, 0, 0, 0, tzinfo=timezone.utc)
                    break
            else:
                break
            continue

        # Clamp day to valid range for month
        max_day = calendar.monthrange(dt.year, dt.month)[1]
        if dt.day > max_day:
            m, y = dt.month + 1, dt.year
            if m > 12:
                m, y = 1, y + 1
            dt = datetime(y, m, 1, 0, 0, 0, tzinfo=timezone.utc)
            continue

        # Check day match (Python weekday: 0=Mon; cron dow: 0=Sun)
        cron_dow = (dt.weekday() + 1) % 7
        if dom_restricted and dow_restricted:
            day_match = (dt.day in doms) or (cron_dow in dows)
        else:
            day_match = (dt.day in doms) and (cron_dow in dows)

        if not day_match:
            dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Advance to next valid hour
        if dt.hour not in hours:
            nh = next((h for h in sorted(hours) if h > dt.hour), None)
            if nh is not None:
                dt = dt.replace(hour=nh, minute=0)
            else:
                dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Advance to next valid minute
        if dt.minute not in minutes:
            nm = next((m for m in sorted(minutes) if m > dt.minute), None)
            if nm is not None:
                dt = dt.replace(minute=nm)
            else:
                nh = next((h for h in sorted(hours) if h > dt.hour), None)
                if nh is not None:
                    dt = dt.replace(hour=nh, minute=min(minutes))
                else:
                    dt = (dt + timedelta(days=1)).replace(hour=min(hours), minute=min(minutes))
            continue

        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    raise ValueError("No matching timestamp found within search limit")
