        for j in range(len(row)):
            while len(cell_lines[j]) < row_height:
                cell_lines[j].append('')

        for vl in range(row_height):
            line = '|'
            for j in range(len(row)):
                text = cell_lines[j][vl]
                aligned = align_text(text, widths[j], aligns[j])
                line += ' ' + aligned + ' |'
            result_lines.append(line)

