from datetime import datetime, timedelta

def next_fire(cron_expr, after_iso):
    def parse_field(field_str, field_min, field_max):
        if field_str == "*":
            return set(range(field_min, field_max + 1))

        values = set()
        for part in field_str.split(","):
            if "/" in part:
                range_part, step = part.split("/")
                step = int(step)
                if range_part == "*":
                    values.update(range(field_min, field_max + 1, step))
                else:
                    start, end = map(int, range_part.split("-"))
                    values.update(range(start, end + 1, step))
            elif "-" in part:
                start, end = map(int, part.split("-"))
                values.update(range(start, end + 1))
            else:
                values.add(int(part))
        return values

    def is_leap_year(year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def days_in_month(year, month):
        if month in [1, 3, 5, 7, 8, 10, 12]:
            return 31
        elif month in [4, 6, 9, 11]:
            return 30
        else:
            return 29 if is_leap_year(year) else 28

    fields = cron_expr.split()
    minute_field, hour_field, day_field, month_field, weekday_field = fields

    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)
    days = parse_field(day_field, 1, 31)
    months = parse_field(month_field, 1, 12)
    weekdays = parse_field(weekday_field, 0, 6)

    day_month_restricted = day_field != "*"
    weekday_restricted = weekday_field != "*"

    weekdays_adjusted = set()
    for wd in weekdays:
        if wd == 0:
            weekdays_adjusted.add(6)
        else:
            weekdays_adjusted.add(wd - 1)

    dt = datetime.fromisoformat(after_iso.replace("Z", "+00:00"))
    dt = dt.replace(second=0, microsecond=0) + timedelta(minutes=1)

    for _ in range(4 * 365 * 24 * 60):
        if dt.day > days_in_month(dt.year, dt.month):
            dt = dt.replace(day=1) + timedelta(days=32)
            dt = dt.replace(day=1, hour=0, minute=0)
            continue

        if (dt.minute in minutes and dt.hour in hours and dt.month in months):
            if day_month_restricted and weekday_restricted:
                day_match = dt.day in days
                weekday_match = dt.weekday() in weekdays_adjusted
                if day_match or weekday_match:
                    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
            else:
                day_match = dt.day in days
                weekday_match = dt.weekday() in weekdays_adjusted
                if day_match and weekday_match:
                    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

        dt += timedelta(minutes=1)

    return None
