def render_table(rows, widths, aligns):
    def wrap_cell(text, width):
        """Wrap a cell's text into visual lines, respecting word boundaries."""
        if not text:
            return ['']

        words = text.split()
        if not words:
            return ['']

        lines = []
        current_line = []

        for word in words:
            if len(word) > width:
                if current_line:
                    lines.append(' '.join(current_line))
                    current_line = []

                for i in range(0, len(word), width):
                    lines.append(word[i:i+width])
            else:
                if not current_line:
                    current_line.append(word)
                elif len(' '.join(current_line)) + 1 + len(word) <= width:
                    current_line.append(word)
                else:
                    lines.append(' '.join(current_line))
                    current_line = [word]

        if current_line:
            lines.append(' '.join(current_line))

        return lines if lines else ['']

    def truncate_cell(lines, width):
        """Truncate cell to max 3 lines and apply ellipsis if needed."""
        if len(lines) <= 3:
            return lines

        truncated = lines[:3]
        third_line = truncated[2]

        if width >= 3:
            truncated[2] = third_line[:width - 3] + '...'
        else:
            truncated[2] = '.' * width

        return truncated

    def align_text(text, width, align):
        """Align text within a column width."""
        extra = width - len(text)
        if extra <= 0:
            return text

        if align == 'l':
            return text + ' ' * extra
        elif align == 'r':
            return ' ' * extra + text
        else:
            left_pad = extra // 2
            right_pad = extra - left_pad
            return ' ' * left_pad + text + ' ' * right_pad

    n = len(widths)

    border_line = '+' + '+'.join('-' * (w + 2) for w in widths) + '+'

    if not rows:
        return border_line + '\n' + border_line

    processed_rows = []

    for row in rows:
        cell_lines = []
        row_height = 1

        for col_idx, cell in enumerate(row):
            wrapped = wrap_cell(cell, widths[col_idx])
            truncated = truncate_cell(wrapped, widths[col_idx])
            cell_lines.append(truncated)
            row_height = max(row_height, len(truncated))

        processed_rows.append((cell_lines, row_height))

    output = [border_line]

    for cell_lines, row_height in processed_rows:
        for line_idx in range(row_height):
            line_parts = []
            for col_idx in range(n):
                if line_idx < len(cell_lines[col_idx]):
                    text = cell_lines[col_idx][line_idx]
                else:
                    text = ''

                aligned = align_text(text, widths[col_idx], aligns[col_idx])
                line_parts.append(' ' + aligned + ' ')

            output.append('|' + '|'.join(line_parts) + '|')

        output.append(border_line)

    return '\n'.join(output)
