                width = widths[cell_idx]
                align = aligns[cell_idx]

                # Get the text for this visual line (or empty if not enough lines)
                if visual_line_idx < len(visual_lines):
                    text = visual_lines[visual_line_idx]
                else:
                    text = ""

                # Align the text
                aligned = _align_text(text, width, align)
                content_parts.append(" " + aligned + " ")
                content_parts.append("|")

            result_lines.append("".join(content_parts))

        # Add border after this row
        result_lines.append(border)

    return "\n".join(result_lines)
