def weighted_interval_schedule(intervals):
    if not intervals:
        return (0, [])

    indexed = [(i, iv[0], iv[1], iv[2], iv[3]) for i, iv in enumerate(intervals)]
    sorted_iv = sorted(indexed, key=lambda x: (x[3], x[2], x[1]))
    n = len(sorted_iv)

    def find_latest_compatible(i):
        start_i = sorted_iv[i][2]
        lo, hi, res = 0, i - 1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if sorted_iv[mid][3] <= start_i:
                res = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return res

    dp = [None] * n
    dp[0] = (sorted_iv[0][4], frozenset([0]))

    for i in range(1, n):
        wi = sorted_iv[i][4]
        w_ex, s_ex = dp[i - 1]

        j = find_latest_compatible(i)
        if j == -1:
            w_in, s_in = wi, frozenset([i])
        else:
            w_pj, s_pj = dp[j]
            w_in, s_in = w_pj + wi, s_pj | frozenset([i])

        w1, w2 = w_ex, w_in
        if w1 != w2:
            dp[i] = (w1, s_ex) if w1 > w2 else (w2, s_in)
        elif len(s_ex) != len(s_in):
            dp[i] = (w1, s_ex) if len(s_ex) < len(s_in) else (w1, s_in)
        else:
            c1 = sorted([sorted_iv[k] for k in s_ex], key=lambda x: (x[3], x[2], x[1]))
            c2 = sorted([sorted_iv[k] for k in s_in], key=lambda x: (x[3], x[2], x[1]))
            st1, st2 = [iv[2] for iv in c1], [iv[2] for iv in c2]
            if st1 != st2:
                dp[i] = (w1, s_ex) if st1 < st2 else (w1, s_in)
            else:
                id1, id2 = [iv[1] for iv in c1], [iv[1] for iv in c2]
                dp[i] = (w1, s_ex) if id1 <= id2 else (w1, s_in)

    best_w, best_s = dp[n - 1]
    chosen = sorted([sorted_iv[i] for i in best_s], key=lambda x: (x[3], x[2], x[1]))
    return (best_w, [iv[1] for iv in chosen])
