"""ASCII table renderer with per-cell word wrapping, truncation, and alignment."""

MAX_LINES = 3


def _wrap_cell(text, width):
    """Wrap a single cell's text into visual lines according to the rules."""
    words = [w for w in text.split(' ') if w != '']

    if not words:
        return ['']

    lines = []
    current = ''
    for word in words:
        if len(word) > width:
            if current != '':
                lines.append(current)
                current = ''
            for i in range(0, len(word), width):
                chunk = word[i:i + width]
                if len(chunk) == width:
                    lines.append(chunk)
                else:
                    current = chunk
            continue
        if current == '':
            current = word
        elif len(current) + 1 + len(word) <= width:
            current = current + ' ' + word
        else:
            lines.append(current)
            current = word

    if current != '':
        lines.append(current)

    if not lines:
        lines = ['']

    return lines


def _truncate_cell(lines, width):
    """Apply the max-lines limit with truncation marker on the third line."""
    if len(lines) <= MAX_LINES:
        return lines

    kept = lines[:MAX_LINES]
    third = kept[2]
    if width >= 3:
        kept[2] = third[:width - 3] + '...'
    else:
        kept[2] = '.' * width
    return kept


def _align_line(text, width, align):
    """Align a single visual line within the column width."""
    extra = width - len(text)
    if extra <= 0:
        return text
    if align == 'l':
        return text + ' ' * extra
    if align == 'r':
        return ' ' * extra + text
    left = extra // 2
    right = extra - left
    return ' ' * left + text + ' ' * right


def _border_line(widths):
    """Build the horizontal border line."""
    parts = ['+']
    for w in widths:
        parts.append('-' * (w + 2))
        parts.append('+')
    return ''.join(parts)


def render_table(rows, widths, aligns):
    """Render an ASCII table from rows, column widths, and alignments."""
    border = _border_line(widths)
    n = len(widths)

    if not rows:
        return border + '\n' + border

    out_lines = [border]

    for row in rows:
        cell_lines = []
        for j in range(n):
            wrapped = _wrap_cell(row[j], widths[j])
            wrapped = _truncate_cell(wrapped, widths[j])
            cell_lines.append(wrapped)

        height = max(len(cl) for cl in cell_lines)

        for vline in range(height):
            pieces = ['|']
            for j in range(n):
                if vline < len(cell_lines[j]):
                    text = cell_lines[j][vline]
                else:
                    text = ''
                aligned = _align_line(text, widths[j], aligns[j])
                pieces.append(' ' + aligned + ' ')
                pieces.append('|')
            out_lines.append(''.join(pieces))

        out_lines.append(border)

    return '\n'.join(out_lines)
