from datetime import datetime, timezone, timedelta
import calendar


def _parse_field(field_str, min_val, max_val):
    values = set()
    for part in field_str.split(','):
        if part == '*':
            values.update(range(min_val, max_val + 1))
        elif '/' in part:
            if part.startswith('*/'):
                step = int(part[2:])
                values.update(range(min_val, max_val + 1, step))
            else:
                range_part, step = part.split('/')
                step = int(step)
                if '-' in range_part:
                    start, end = map(int, range_part.split('-'))
                else:
                    start = int(range_part)
                    end = max_val
                values.update(range(start, end + 1, step))
        elif '-' in part:
            start, end = map(int, part.split('-'))
            values.update(range(start, end + 1))
        else:
            values.add(int(part))
    return values


def _day_matches(dt, doms, dows, dom_restricted, dow_restricted):
    cron_dow = (dt.weekday() + 1) % 7
    dom_val = dt.day
    max_day = calendar.monthrange(dt.year, dt.month)[1]
    valid_doms = {d for d in doms if d <= max_day}

    if dom_restricted and dow_restricted:
        return (dom_val in valid_doms) or (cron_dow in dows)
    elif dom_restricted:
        return dom_val in valid_doms
    elif dow_restricted:
        return cron_dow in dows
    else:
        return True


def next_fire(cron_expr, after_iso):
    minute_str, hour_str, dom_str, month_str, dow_str = cron_expr.split()

    minutes = _parse_field(minute_str, 0, 59)
    hours = _parse_field(hour_str, 0, 23)
    doms = _parse_field(dom_str, 1, 31)
    months = _parse_field(month_str, 1, 12)
    dows = _parse_field(dow_str, 0, 6)

    dom_restricted = dom_str != '*'
    dow_restricted = dow_str != '*'

    dt = datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    dt = (dt + timedelta(minutes=1)).replace(second=0, microsecond=0)

    max_iterations = 366 * 24 * 60 * 10

    for _ in range(max_iterations):
        if dt.month not in months:
            next_month = next((m for m in sorted(months) if m > dt.month), None)
            if next_month is None:
                dt = dt.replace(year=dt.year + 1, month=min(months), day=1, hour=0, minute=0)
            else:
                dt = dt.replace(month=next_month, day=1, hour=0, minute=0)
            continue

        if not _day_matches(dt, doms, dows, dom_restricted, dow_restricted):
            dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if dt.hour not in hours:
            next_hour = next((h for h in sorted(hours) if h > dt.hour), None)
            if next_hour is None:
                dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
            else:
                dt = dt.replace(hour=next_hour, minute=0)
            continue

        if dt.minute not in minutes:
            next_minute = next((m for m in sorted(minutes) if m > dt.minute), None)
            if next_minute is None:
                dt = (dt + timedelta(hours=1)).replace(minute=0)
            else:
                dt = dt.replace(minute=next_minute)
            continue

        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    raise ValueError("No matching timestamp found within search limit")
