from datetime import datetime, timezone, timedelta
import calendar


def _parse_field(field_str, min_val, max_val):
    values = set()
    for part in field_str.split(','):
        if part == '*':
            values.update(range(min_val, max_val + 1))
        elif '/' in part:
            base, step = part.split('/', 1)
            step = int(step)
            if '-' in base:
                start, end = base.split('-')
                start, end = int(start), int(end)
            elif base == '*':
                start, end = min_val, max_val
            else:
                start, end = int(base), max_val
            values.update(range(start, end + 1, step))
        elif '-' in part:
            start, end = part.split('-')
            values.update(range(int(start), int(end) + 1))
        else:
            values.add(int(part))
    return values


def _is_restricted(field_str):
    return field_str != '*'


def _days_in_month(year, month):
    return calendar.monthrange(year, month)[1]


def _date_matches(day, month, year, dom_values, dow_values, dom_restricted, dow_restricted):
    dt = datetime(year, month, day, tzinfo=timezone.utc)
    cron_dow = (dt.weekday() + 1) % 7
    dom_matches = day in dom_values
    dow_matches = cron_dow in dow_values
    if dom_restricted and dow_restricted:
        return dom_matches or dow_matches
    return dom_matches and dow_matches


def next_fire(cron_expr, after_iso):
    minute_str, hour_str, dom_str, month_str, dow_str = cron_expr.split()

    minute_values = _parse_field(minute_str, 0, 59)
    hour_values   = _parse_field(hour_str,   0, 23)
    dom_values    = _parse_field(dom_str,    1, 31)
    month_values  = _parse_field(month_str,  1, 12)
    dow_values    = _parse_field(dow_str,    0,  6)

    dom_restricted = _is_restricted(dom_str)
    dow_restricted = _is_restricted(dow_str)

    after_dt = datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    current  = (after_dt + timedelta(minutes=1)).replace(second=0, microsecond=0)

    for _ in range(5 * 366 * 24 * 60):
        y, mo, d, h, mi = current.year, current.month, current.day, current.hour, current.minute

        if mo not in month_values:
            nxt = next((m for m in sorted(month_values) if m > mo), None)
            if nxt is None:
                current = datetime(y + 1, min(month_values), 1, 0, 0, tzinfo=timezone.utc)
            else:
                current = datetime(y, nxt, 1, 0, 0, tzinfo=timezone.utc)
            continue

        if not _date_matches(d, mo, y, dom_values, dow_values, dom_restricted, dow_restricted):
            nd = d + 1
            max_d = _days_in_month(y, mo)
            if nd > max_d:
                if mo == 12:
                    current = datetime(y + 1, 1, 1, 0, 0, tzinfo=timezone.utc)
                else:
                    current = datetime(y, mo + 1, 1, 0, 0, tzinfo=timezone.utc)
            else:
                current = datetime(y, mo, nd, 0, 0, tzinfo=timezone.utc)
            continue

        if h not in hour_values:
            nxt = next((hv for hv in sorted(hour_values) if hv > h), None)
            if nxt is None:
                nd = d + 1
                max_d = _days_in_month(y, mo)
                if nd > max_d:
                    if mo == 12:
                        current = datetime(y + 1, 1, 1, 0, 0, tzinfo=timezone.utc)
                    else:
                        current = datetime(y, mo + 1, 1, 0, 0, tzinfo=timezone.utc)
                else:
                    current = datetime(y, mo, nd, 0, 0, tzinfo=timezone.utc)
            else:
                current = datetime(y, mo, d, nxt, 0, tzinfo=timezone.utc)
            continue

        if mi not in minute_values:
            nxt = next((mv for mv in sorted(minute_values) if mv > mi), None)
            if nxt is None:
                nxth = next((hv for hv in sorted(hour_values) if hv > h), None)
                if nxth is None:
                    nd = d + 1
                    max_d = _days_in_month(y, mo)
                    if nd > max_d:
                        if mo == 12:
                            current = datetime(y + 1, 1, 1, 0, 0, tzinfo=timezone.utc)
                        else:
                            current = datetime(y, mo + 1, 1, 0, 0, tzinfo=timezone.utc)
                    else:
                        current = datetime(y, mo, nd, 0, 0, tzinfo=timezone.utc)
                else:
                    current = datetime(y, mo, d, nxth, 0, tzinfo=timezone.utc)
            else:
                current = datetime(y, mo, d, h, nxt, tzinfo=timezone.utc)
            continue

        return current.strftime("%Y-%m-%dT%H:%M:%SZ")

    raise ValueError("No matching timestamp found within search limit")
