from datetime import datetime, timedelta, timezone


def _parse_field(field: str, min_val: int, max_val: int):
    result = set()
    for part in field.split(','):
        if part == '*':
            result.update(range(min_val, max_val + 1))
        elif '/' in part:
            left, step_s = part.split('/', 1)
            step = int(step_s)
            if left == '*':
                start, end = min_val, max_val
            elif '-' in left:
                start_s, end_s = left.split('-', 1)
                start, end = int(start_s), int(end_s)
            else:
                start = int(left)
                end = max_val
            result.update(range(start, end + 1, step))
        elif '-' in part:
            start_s, end_s = part.split('-', 1)
            result.update(range(int(start_s), int(end_s) + 1))
        else:
            result.add(int(part))
    return result


def next_fire(cron_expr: str, after_iso: str) -> str:
    minute_field, hour_field, dom_field, month_field, dow_field = cron_expr.split()

    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    doms = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12)
    dows = _parse_field(dow_field, 0, 6)

    dom_restricted = dom_field.strip() != '*'
    dow_restricted = dow_field.strip() != '*'

    dt = datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    dt = (dt + timedelta(minutes=1)).replace(second=0, microsecond=0)

    while True:
        # Check month
        if dt.month not in months:
            found = False
            for m in range(dt.month + 1, 13):
                if m in months:
                    dt = datetime(dt.year, m, 1, 0, 0, 0, tzinfo=timezone.utc)
                    found = True
                    break
            if not found:
                dt = datetime(dt.year + 1, 1, 1, 0, 0, 0, tzinfo=timezone.utc)
            continue

        # Check day (with classic cron OR-logic when both fields are restricted)
        # Python weekday(): 0=Monday ... 6=Sunday; cron dow: 0=Sunday ... 6=Saturday
        cron_dow = (dt.weekday() + 1) % 7
        dom_matches = dt.day in doms
        dow_matches = cron_dow in dows

        if dom_restricted and dow_restricted:
            day_matches = dom_matches or dow_matches
        else:
            day_matches = dom_matches and dow_matches

        if not day_matches:
            dt = datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=timezone.utc) + timedelta(days=1)
            continue

        # Check hour
        if dt.hour not in hours:
            next_hour = next((h for h in sorted(hours) if h > dt.hour), None)
            if next_hour is None:
                dt = datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=timezone.utc) + timedelta(days=1)
            else:
                dt = datetime(dt.year, dt.month, dt.day, next_hour, 0, 0, tzinfo=timezone.utc)
            continue

        # Check minute
        if dt.minute not in minutes:
            next_minute = next((m for m in sorted(minutes) if m > dt.minute), None)
            if next_minute is None:
                dt = datetime(dt.year, dt.month, dt.day, dt.hour, 0, 0, tzinfo=timezone.utc) + timedelta(hours=1)
            else:
                dt = datetime(dt.year, dt.month, dt.day, dt.hour, next_minute, 0, tzinfo=timezone.utc)
            continue

        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
