def render_table(rows, widths, aligns):
    border = _make_border(widths)

    if not rows:
        return border + '\n' + border

    result_lines = [border]

    for row in rows:
        visual_cells = []
        for j, cell in enumerate(row):
            lines = _wrap_cell(cell, widths[j])
            visual_cells.append(lines)

        row_height = max(len(cell) for cell in visual_cells)

        for vi in range(row_height):
            line = '|'
            for j, cell_lines in enumerate(visual_cells):
                if vi < len(cell_lines):
                    text = cell_lines[vi]
                else:
                    text = ''
                aligned = _align(text, widths[j], aligns[j])
                line += ' ' + aligned + ' |'
            result_lines.append(line)

        result_lines.append(border)

    return '\n'.join(result_lines)


def _make_border(widths):
    parts = ['+']
    for w in widths:
        parts.append('-' * (w + 2))
        parts.append('+')
    return ''.join(parts)


def _wrap_cell(text, width):
    if text == '':
        return ['']

    words = text.split(' ')
    words = [w for w in words if w != '']

    if not words:
        return ['']

    lines = []
    current_line = ''

    i = 0
    while i < len(words):
        word = words[i]

        if len(word) > width:
            if current_line:
                lines.append(current_line)
                current_line = ''
            chunks = _hard_break(word, width)
            lines.extend(chunks)
            i += 1
        else:
            if current_line == '':
                current_line = word
            elif len(current_line) + 1 + len(word) <= width:
                current_line += ' ' + word
            else:
                lines.append(current_line)
                current_line = word
            i += 1

    if current_line:
        lines.append(current_line)

    if not lines:
        return ['']

    max_lines = 3
    if len(lines) <= max_lines:
        return lines

    lines = lines[:max_lines]
    if width >= 3:
        lines[2] = lines[2][:width - 3] + '...'
    else:
        lines[2] = '.' * width

    return lines


def _hard_break(word, width):
    chunks = []
    start = 0
    while start < len(word):
        chunks.append(word[start:start + width])
        start += width
    return chunks


def _align(text, width, align):
    extra = width - len(text)
    if extra <= 0:
        return text

    if align == 'l':
        return text + ' ' * extra
    elif align == 'r':
        return ' ' * extra + text
    else:  # 'c'
        left_pad = extra // 2
        right_pad = extra - left_pad
        return ' ' * left_pad + text + ' ' * right_pad
