    return '\n'.join(lines)


def _make_border(widths):
    parts = ['+']
    for w in widths:
        parts.append('-' * (w + 2))
        parts.append('+')
    return ''.join(parts)


def _wrap_cell(text, width):
    if not text:
        return ['']

    words = text.split(' ')
    words = [w for w in words if w != '']

    if not words:
        return ['']

    visual_lines = []
    current_line = ''

    for word in words:
        if len(word) > width:
            if current_line:
                visual_lines.append(current_line)
                current_line = ''
            for i in range(0, len(word), width):
                chunk = word[i:i+width]
                visual_lines.append(chunk)
        else:
            if current_line == '':
                current_line = word
            elif len(current_line) + 1 + len(word) <= width:
                current_line += ' ' + word
            else:
                visual_lines.append(current_line)
                current_line = word

    if current_line:
        visual_lines.append(current_line)

    return visual_lines if visual_lines else ['']


def _truncate_cell(visual_lines, width, max_lines=3):
    if len(visual_lines) <= max_lines:
        return list(visual_lines)

    truncated = list(visual_lines[:max_lines])
    if width >= 3:
        truncated[2] = truncated[2][:width - 3] + '...'
    else:
        truncated[2] = '.' * width

    return truncated


def _align_text(text, width, align):
    extra = width - len(text)
    if extra <= 0:
        return text[:width]

    if align == 'l':
        return text + ' ' * extra
    elif align == 'r':
        return ' ' * extra + text
    elif align == 'c':
        left_pad = extra // 2
        right_pad = extra - left_pad
        return ' ' * left_pad + text + ' ' * right_pad
    return text


def _render_row(row, widths, aligns):
    cell_lines = []
    for i, cell in enumerate(row):
        wrapped = _wrap_cell(cell, widths[i])
        truncated = _truncate_cell(wrapped, widths[i])
        cell_lines.append(truncated)

    row_height = max(len(cl) for cl in cell_lines)

    padded_cells = []
    for cl in cell_lines:
        padded = list(cl)
        while len(padded) < row_height:
            padded.append('')
        padded_cells.append(padded)

    visual_lines = []
    for line_idx in range(row_height):
        parts = ['|']
        for col_idx, cell_line_list in enumerate(padded_cells):
            text = cell_line_list[line_idx]
            aligned = _align_text(text, widths[col_idx], aligns[col_idx])
            parts.append(' ' + aligned + ' |')
        visual_lines.append(''.join(parts))

    return visual_lines
