        for word in words:
            if len(word) > width:
                if current:
                    lines.append(current)
                    current = ''
                idx = 0
                while idx < len(word):
                    lines.append(word[idx:idx + width])
                    idx += width
            else:
                if current == '':
                    current = word
                elif len(current) + 1 + len(word) <= width:
                    current = current + ' ' + word
                else:
                    lines.append(current)
                    current = word
        if current:
            lines.append(current)
        return lines if lines else ['']

    def _truncate(lines, width):
        if len(lines) <= 3:
            return lines
        kept = list(lines[:3])
        if width >= 3:
            kept[2] = kept[2][:width - 3] + '...'
        else:
            kept[2] = '.' * width
        return kept

    def _align(text, width, align):
