        if extra <= 0:
            return text[:width]
        if align == 'l':
            return text + ' ' * extra
        elif align == 'r':
            return ' ' * extra + text
        else:
            lp = extra // 2
            rp = extra - lp
            return ' ' * lp + text + ' ' * rp

    output_lines = [border]

    for row_idx, row in enumerate(rows):
        if row_idx > 0:
            output_lines.append(border)

        cell_lines = []
        for j in range(n):
            wrapped = _wrap_cell(row[j], widths[j])
            cell_lines.append(_truncate(wrapped, widths[j]))

        row_height = max(len(cl) for cl in cell_lines)

        for j in range(n):
            while len(cell_lines[j]) < row_height:
                cell_lines[j].append('')

