from bisect import bisect_right


def weighted_interval_schedule(intervals):
    if not intervals:
        return (0, [])

    n = len(intervals)

    sorted_intervals = sorted(intervals, key=lambda x: (x[2], x[1], x[0]))
    end_times = [iv[2] for iv in sorted_intervals]

    def find_last_compatible(idx):
        start_idx = sorted_intervals[idx][1]
        pos = bisect_right(end_times, start_idx, 0, idx) - 1
        return pos

    def better(sol_a, w_a, sol_b, w_b):
        if w_a != w_b:
            return (sol_a, w_a) if w_a > w_b else (sol_b, w_b)
        if len(sol_a) != len(sol_b):
            return (sol_a, w_a) if len(sol_a) < len(sol_b) else (sol_b, w_b)
        starts_a = [sorted_intervals[i][1] for i in sol_a]
        starts_b = [sorted_intervals[i][1] for i in sol_b]
        if starts_a != starts_b:
            return (sol_a, w_a) if starts_a < starts_b else (sol_b, w_b)
        ids_a = [sorted_intervals[i][0] for i in sol_a]
        ids_b = [sorted_intervals[i][0] for i in sol_b]
        return (sol_a, w_a) if ids_a <= ids_b else (sol_b, w_b)

    opt_weight = [0] * n
    opt_sol = [[] for _ in range(n)]

    for i in range(n):
        w_i = sorted_intervals[i][3]
        last = find_last_compatible(i)

        if last < 0:
            inc_w = w_i
            inc_sol = [i]
        else:
            inc_w = opt_weight[last] + w_i
            inc_sol = opt_sol[last] + [i]

        if i == 0:
            exc_w, exc_sol = 0, []
        else:
            exc_w, exc_sol = opt_weight[i - 1], opt_sol[i - 1]

        opt_sol[i], opt_weight[i] = better(inc_sol, inc_w, exc_sol, exc_w)

    final_weight = opt_weight[n - 1]
    chosen_ids = [sorted_intervals[i][0] for i in opt_sol[n - 1]]
    return (final_weight, chosen_ids)
