from datetime import datetime, timedelta


def _parse_field(field, lo, hi):
    values = set()
    for item in field.split(","):
        step = 1
        if "/" in item:
            item, step_str = item.split("/")
            step = int(step_str)
        if item == "*":
            start, end = lo, hi
        elif "-" in item:
            a, b = item.split("-")
            start, end = int(a), int(b)
        else:
            start = end = int(item)
        values.update(range(start, end + 1, step))
    return values


def next_fire(cron_expr, after_iso):
    f_min, f_hour, f_dom, f_mon, f_dow = cron_expr.split()

    minutes = sorted(_parse_field(f_min, 0, 59))
    hours = sorted(_parse_field(f_hour, 0, 23))
    doms = _parse_field(f_dom, 1, 31)
    months = _parse_field(f_mon, 1, 12)
    dows = _parse_field(f_dow, 0, 6)

    dom_star = f_dom == "*"
    dow_star = f_dow == "*"

    def day_matches(d):
        if d.month not in months:
            return False
        dom_match = d.day in doms
        # Python: Monday=0..Sunday=6 -> cron: Sunday=0..Saturday=6
        dow_match = ((d.weekday() + 1) % 7) in dows
        if not dom_star and not dow_star:
            return dom_match or dow_match
        return dom_match and dow_match

    after = datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ")
    cur = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    while True:
        if day_matches(cur):
            for h in hours:
                if h < cur.hour:
                    continue
                for m in minutes:
                    if h == cur.hour and m < cur.minute:
                        continue
                    return cur.replace(hour=h, minute=m).strftime(
                        "%Y-%m-%dT%H:%M:%SZ"
                    )
        cur = (cur + timedelta(days=1)).replace(hour=0, minute=0)
