import datetime


def _parse_field(field, lo, hi):
    values = set()
    for item in field.split(','):
        step = 1
        if '/' in item:
            base, step_str = item.split('/')
            step = int(step_str)
        else:
            base = item
        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            a, b = base.split('-')
            start, end = int(a), int(b)
        else:
            start = end = int(base)
        values.update(range(start, end + 1, step))
    return values


def next_fire(cron_expr, after_iso):
    f_min, f_hour, f_dom, f_mon, f_dow = cron_expr.split()

    minutes = sorted(_parse_field(f_min, 0, 59))
    hours = sorted(_parse_field(f_hour, 0, 23))
    doms = _parse_field(f_dom, 1, 31)
    months = _parse_field(f_mon, 1, 12)
    dows = _parse_field(f_dow, 0, 6)

    dom_star = (f_dom == '*')
    dow_star = (f_dow == '*')

    def day_matches(d):
        if d.month not in months:
            return False
        dom_ok = d.day in doms
        # Python: Monday=0..Sunday=6 -> cron: Sunday=0..Saturday=6
        dow_ok = ((d.weekday() + 1) % 7) in dows
        if dom_star and dow_star:
            return True
        if dom_star:
            return dow_ok
        if dow_star:
            return dom_ok
        return dom_ok or dow_ok

    after = datetime.datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ")
    start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    cur_date = start.date()
    first_day = True
    for _ in range(366 * 30):
        if day_matches(cur_date):
            if first_day:
                start_h, start_m = start.hour, start.minute
            else:
                start_h, start_m = 0, 0
            for h in hours:
                if h < start_h:
                    continue
                for m in minutes:
                    if h == start_h and m < start_m:
                        continue
                    result = datetime.datetime(
                        cur_date.year, cur_date.month, cur_date.day, h, m
                    )
                    return result.strftime("%Y-%m-%dT%H:%M:%SZ")
        cur_date += datetime.timedelta(days=1)
        first_day = False

    raise ValueError("no matching timestamp found")
