"""ASCII table renderer with per-cell word wrapping, truncation, and alignment."""


def _wrap_cell(text, width):
    """Wrap a single cell's text into visual lines for the given width."""
    words = [w for w in text.split(' ') if w]
    lines = []
    cur = ''
    for word in words:
        if len(word) > width:
            if cur:
                lines.append(cur)
                cur = ''
            for i in range(0, len(word), width):
                lines.append(word[i:i + width])
        elif cur:
            if len(cur) + 1 + len(word) <= width:
                cur = cur + ' ' + word
            else:
                lines.append(cur)
                cur = word
        else:
            cur = word
    if cur:
        lines.append(cur)
    if not lines:
        lines = ['']
    return lines


def _truncate_lines(lines, width):
    """Apply the 3-line limit with ellipsis replacement on the third line."""
    if len(lines) <= 3:
        return lines
    kept = lines[:3]
    if width >= 3:
        kept[2] = kept[2][:width - 3] + '...'
    else:
        kept[2] = '.' * width
    return kept


def _align_text(text, width, code):
    """Pad text to exactly width characters per the alignment code."""
    extra = width - len(text)
    if code == 'l':
        return text + ' ' * extra
    if code == 'r':
        return ' ' * extra + text
    left = extra // 2
    return ' ' * left + text + ' ' * (extra - left)


def render_table(rows, widths, aligns):
    """Render rows as an ASCII table with the given column widths and alignments."""
    border = '+' + '+'.join('-' * (w + 2) for w in widths) + '+'
    out = [border]
    if not rows:
        out.append(border)
        return '\n'.join(out)
    n = len(widths)
    for row in rows:
        cells = [
            _truncate_lines(_wrap_cell(row[j], widths[j]), widths[j])
            for j in range(n)
        ]
        height = max(len(c) for c in cells)
        for c in cells:
            c.extend([''] * (height - len(c)))
        for i in range(height):
            parts = [
                ' ' + _align_text(cells[j][i], widths[j], aligns[j]) + ' '
                for j in range(n)
            ]
            out.append('|' + '|'.join(parts) + '|')
        out.append(border)
    return '\n'.join(out)
