"""ASCII table renderer with per-cell word wrapping, truncation, and alignment."""


def _wrap_cell(text, width):
    """Wrap a single cell's text into visual lines for the given width."""
    words = [w for w in text.split(' ') if w]
    if not words:
        return ['']
    lines = []
    current = None  # current line being built, or None if no line in progress
    for word in words:
        if len(word) > width:
            # Flush any in-progress line, then hard-break the word.
            if current is not None:
                lines.append(current)
                current = None
            for i in range(0, len(word), width):
                lines.append(word[i:i + width])
            # Chunks from a hard-broken word are never merged with following words.
        else:
            if current is None:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current = current + ' ' + word
            else:
                lines.append(current)
                current = word
    if current is not None:
        lines.append(current)
    return lines if lines else ['']


def _truncate(lines, width, max_lines=3):
    """Keep at most max_lines lines, marking truncation on the last kept line."""
    if len(lines) <= max_lines:
        return list(lines)
    kept = lines[:max_lines]
    if width >= 3:
        kept[-1] = kept[-1][:width - 3] + '...'
    else:
        kept[-1] = '.' * width
    return kept


def _align(text, width, code):
    """Pad text to exactly width characters according to the alignment code."""
    extra = width - len(text)
    if code == 'l':
        return text + ' ' * extra
    if code == 'r':
        return ' ' * extra + text
    left = extra // 2
    return ' ' * left + text + ' ' * (extra - left)


def render_table(rows, widths, aligns):
    """Render rows as an ASCII table with the given column widths and alignments."""
    border = '+' + '+'.join('-' * (w + 2) for w in widths) + '+'
    if not rows:
        return border + '\n' + border
    out = [border]
    for row in rows:
        cells = [
            _truncate(_wrap_cell(cell, width), width)
            for cell, width in zip(row, widths)
        ]
        height = max(len(cell) for cell in cells)
        for i in range(height):
            parts = []
            for j, cell in enumerate(cells):
                text = cell[i] if i < len(cell) else ''
                parts.append(' ' + _align(text, widths[j], aligns[j]) + ' ')
            out.append('|' + '|'.join(parts) + '|')
        out.append(border)
    return '\n'.join(out)
