from dataclasses import dataclass


ESCAPES = {
    "n": "\n",
    "t": "\t",
    "r": "\r",
    '"': '"',
    "\\": "\\",
}

SINGLE_OPS = set("+-*/()=<>!,")
DOUBLE_OPS = {"<=", ">=", "==", "!="}


def _is_digit(ch):
    return ch is not None and "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch is not None and (ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z")


def _is_ident_part(ch):
    return _is_ident_start(ch) or _is_digit(ch)


@dataclass(frozen=True)
class Token:
    kind: str
    value: str
    line: int
    col: int


def tokenize(text):
    tokens = []
    i = 0
    line = 1
    col = 1
    n = len(text)

    def peek(offset=0):
        j = i + offset
        return text[j] if j < n else None

    def advance():
        nonlocal i, line, col
        ch = text[i]
        i += 1
        if ch == "\n":
            line += 1
            col = 1
        else:
            col += 1
        return ch

    while i < n:
        ch = peek()
        if ch in " \t\r\n":
            advance()
            continue
        if ch == "#":
            while i < n and peek() != "\n":
                advance()
            if i < n:
                advance()
            continue

        start_line = line
        start_col = col
        pair = (ch or "") + (peek(1) or "")
        if pair in DOUBLE_OPS:
            advance()
            advance()
            tokens.append(Token("OP", pair, start_line, start_col))
            continue
        if ch in SINGLE_OPS:
            advance()
            tokens.append(Token("OP", ch, start_line, start_col))
            continue
        if _is_ident_start(ch):
            chars = [advance()]
            while i < n and _is_ident_part(peek()):
                chars.append(advance())
            tokens.append(Token("IDENT", "".join(chars), start_line, start_col))
            continue
        if _is_digit(ch) or (ch == "." and _is_digit(peek(1))):
            chars = []
            while i < n and _is_digit(peek()):
                chars.append(advance())
            if peek() == ".":
                chars.append(advance())
                while i < n and _is_digit(peek()):
                    chars.append(advance())
            tokens.append(Token("NUMBER", "".join(chars), start_line, start_col))
            continue
        if ch == '"':
            advance()
            chars = []
            closed = False
            while i < n:
                current = peek()
                if current == '"':
                    advance()
                    closed = True
                    break
                if current == "\\":
                    advance()
                    if i >= n:
                        raise SyntaxError(
                            f"unterminated escape at {start_line}:{start_col}"
                        )
                    esc = advance()
                    chars.append(ESCAPES.get(esc, esc))
                    continue
                chars.append(advance())
            if not closed:
                raise SyntaxError(f"unterminated string at {start_line}:{start_col}")
            tokens.append(Token("STRING", "".join(chars), start_line, start_col))
            continue
        raise SyntaxError(f"unexpected character {ch!r} at {start_line}:{start_col}")

    return tokens
