from bisect import bisect_right


def weighted_interval_schedule(intervals):
    if not intervals:
        return (0, [])

    # Sort by (end, start, id) — this is also the required output ordering
    sorted_ivs = sorted(intervals, key=lambda x: (x[2], x[1], x[0]))
    n = len(sorted_ivs)
    end_times = [iv[2] for iv in sorted_ivs]

    def last_compatible(j):
        # Largest index p such that end_times[p] <= start of interval j
        # Half-open semantics: end <= start means no overlap (touching is compatible)
        return bisect_right(end_times, sorted_ivs[j][1]) - 1

    def is_better(w1, s1, w2, s2):
        """Return True if (w1, s1) strictly beats (w2, s2) under the tie-break hierarchy."""
        if w1 != w2:
            return w1 > w2
        if len(s1) != len(s2):
            return len(s1) < len(s2)
        starts1 = [sorted_ivs[i][1] for i in s1]
        starts2 = [sorted_ivs[i][1] for i in s2]
        if starts1 != starts2:
            return starts1 < starts2
        ids1 = [sorted_ivs[i][0] for i in s1]
        ids2 = [sorted_ivs[i][0] for i in s2]
        return ids1 < ids2

    # dp_w[i], dp_s[i]: best weight and schedule (list of indices into sorted_ivs)
    # over all subsets of the first i intervals
    dp_w = [0] * (n + 1)
    dp_s = [[]] * (n + 1)

    for j in range(n):
        c = last_compatible(j) + 1  # dp index for the best schedule compatible with j

        inc_w = dp_w[c] + sorted_ivs[j][3]
        inc_s = dp_s[c] + [j]
        exc_w = dp_w[j]
        exc_s = dp_s[j]

        if is_better(inc_w, inc_s, exc_w, exc_s):
            dp_w[j + 1], dp_s[j + 1] = inc_w, inc_s
        else:
            dp_w[j + 1], dp_s[j + 1] = exc_w, exc_s

    chosen_ids = [sorted_ivs[i][0] for i in dp_s[n]]
    return (dp_w[n], chosen_ids)
