from bisect import bisect_right


def weighted_interval_schedule(intervals):
    if not intervals:
        return (0, [])

    sorted_intervals = sorted(intervals, key=lambda x: (x[2], x[1], x[0]))
    n = len(sorted_intervals)
    end_times = [iv[2] for iv in sorted_intervals]

    def latest_compatible(i):
        start_i = sorted_intervals[i][1]
        return bisect_right(end_times, start_i) - 1

    def solution_key(weight, chosen_indices):
        chosen = [sorted_intervals[idx] for idx in chosen_indices]
        starts = tuple(iv[1] for iv in chosen)
        ids = tuple(iv[0] for iv in chosen)
        return (weight, -len(chosen_indices), starts, ids)

    def better(key1, key2):
        w1, nc1, s1, i1 = key1
        w2, nc2, s2, i2 = key2
        if w1 != w2:
            return w1 > w2
        if nc1 != nc2:
            return nc1 > nc2
        if s1 != s2:
            return s1 < s2
        return i1 < i2

    best_solutions = []

    for i in range(n):
        weight_i = sorted_intervals[i][3]
        j = latest_compatible(i)

        if j >= 0:
            prev_w, prev_chosen = best_solutions[j]
            include_w = prev_w + weight_i
            include_chosen = prev_chosen + [i]
        else:
            include_w = weight_i
            include_chosen = [i]

        include_key = solution_key(include_w, include_chosen)

        if i > 0:
            exclude_w, exclude_chosen = best_solutions[i - 1]
            exclude_key = solution_key(exclude_w, exclude_chosen)
        else:
            exclude_w, exclude_chosen = 0, []
            exclude_key = solution_key(0, [])

        if better(include_key, exclude_key):
            best_solutions.append((include_w, include_chosen))
        else:
            best_solutions.append((exclude_w, exclude_chosen))

    final_w, final_chosen = best_solutions[n - 1]
    chosen_ids = [sorted_intervals[idx][0] for idx in final_chosen]
    return (final_w, chosen_ids)
