from datetime import datetime, timedelta
import calendar

def _parse_field(field, min_val, max_val):
    result = set()
    parts = field.split(',')
    for part in parts:
        if part == '*':
            result.update(range(min_val, max_val + 1))
        elif '/' in part:
            if '-' in part.split('/')[0]:
                range_part, step = part.split('/')
                start, end = range_part.split('-')
                step = int(step)
                result.update(range(int(start), int(end) + 1, step))
            else:
                base, step = part.split('/')
                step = int(step)
                if base == '*':
                    result.update(range(min_val, max_val + 1, step))
                else:
                    result.update(range(int(base), max_val + 1, step))
        elif '-' in part:
            start, end = part.split('-')
            result.update(range(int(start), int(end) + 1))
        else:
            result.add(int(part))
    return result

def _is_restricted(field):
    return field != '*'

def next_fire(cron_expr, after_iso):
    fields = cron_expr.split()
    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    doms = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12)
    dows = _parse_field(dow_field, 0, 6)

    dom_restricted = _is_restricted(dom_field)
    dow_restricted = _is_restricted(dow_field)

    dt = datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ")
    dt = dt + timedelta(minutes=1)
    dt = dt.replace(second=0, microsecond=0)

    max_iterations = 527040 * 5  # ~5 years of minutes

    for _ in range(max_iterations):
        if dt.month not in months:
            next_month = min((m for m in months if m > dt.month), default=None)
            if next_month is None:
                dt = dt.replace(year=dt.year + 1, month=min(months), day=1, hour=0, minute=0)
            else:
                dt = dt.replace(month=next_month, day=1, hour=0, minute=0)
            continue

        max_day = calendar.monthrange(dt.year, dt.month)[1]

        if dom_restricted and dow_restricted:
            dom_ok = dt.day in doms and dt.day <= max_day
            py_dow = dt.weekday()  # 0=Mon, 6=Sun
            cron_dow = (py_dow + 1) % 7  # Mon=1..Sun=0
            dow_ok = cron_dow in dows
            day_matches = dom_ok or dow_ok
        else:
            py_dow = dt.weekday()
            cron_dow = (py_dow + 1) % 7
            dom_ok = dt.day in doms and dt.day <= max_day
            dow_ok = cron_dow in dows
            day_matches = dom_ok and dow_ok

        if not day_matches:
            dt = dt + timedelta(days=1)
            dt = dt.replace(hour=0, minute=0)
            continue

        if dt.hour not in hours:
            next_hour = min((h for h in hours if h > dt.hour), default=None)
            if next_hour is None:
                dt = dt + timedelta(days=1)
                dt = dt.replace(hour=0, minute=0)
            else:
                dt = dt.replace(hour=next_hour, minute=0)
            continue

        if dt.minute not in minutes:
            next_minute = min((m for m in minutes if m > dt.minute), default=None)
            if next_minute is None:
                next_hour = min((h for h in hours if h > dt.hour), default=None)
                if next_hour is None:
                    dt = dt + timedelta(days=1)
                    dt = dt.replace(hour=0, minute=0)
                else:
                    dt = dt.replace(hour=next_hour, minute=0)
            else:
                dt = dt.replace(minute=next_minute)
            continue

        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    raise ValueError("No matching timestamp found within search limit")
