from datetime import datetime, timedelta, timezone
import calendar


def _parse_field(field: str, min_val: int, max_val: int):
    values = set()
    for part in field.split(','):
        if part == '*':
            values.update(range(min_val, max_val + 1))
        elif '/' in part:
            range_part, step_str = part.split('/', 1)
            step = int(step_str)
            if range_part == '*':
                start = min_val
                end = max_val
            elif '-' in range_part:
                start, end = map(int, range_part.split('-', 1))
            else:
                start = int(range_part)
                end = max_val
            values.update(range(start, end + 1, step))
        elif '-' in part:
            start, end = map(int, part.split('-', 1))
            values.update(range(start, end + 1))
        else:
            values.add(int(part))
    return values


def next_fire(cron_expr: str, after_iso: str) -> str:
    fields = cron_expr.split()
    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    doms = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12)
    dows = _parse_field(dow_field, 0, 6)

    dom_restricted = dom_field != '*'
    dow_restricted = dow_field != '*'

    dt = datetime.strptime(after_iso, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    dt = dt + timedelta(minutes=1)
    dt = dt.replace(second=0, microsecond=0)

    for _ in range(366 * 24 * 60 * 5):
        if dt.month not in months:
            year = dt.year
            month = dt.month
            next_month = None
            for m in sorted(months):
                if m > month:
                    next_month = m
                    break
            if next_month is None:
                year += 1
                next_month = min(months)
            dt = datetime(year, next_month, 1, 0, 0, 0, tzinfo=timezone.utc)
            continue

        days_in_month = calendar.monthrange(dt.year, dt.month)[1]
        if dt.day > days_in_month:
            month = dt.month + 1
            year = dt.year
            if month > 12:
                month = 1
                year += 1
            dt = datetime(year, month, 1, 0, 0, 0, tzinfo=timezone.utc)
            continue

        # Python isoweekday(): Mon=1..Sun=7 -> cron dow: Sun=0, Mon=1..Sat=6
        cron_dow = dt.isoweekday() % 7

        dom_match = dt.day in doms
        dow_match = cron_dow in dows

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            dom_ok = dom_match if dom_restricted else True
            dow_ok = dow_match if dow_restricted else True
            day_match = dom_ok and dow_ok

        if not day_match:
            dt = datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=timezone.utc) + timedelta(days=1)
            continue

        if dt.hour not in hours:
            next_hour = None
            for h in sorted(hours):
                if h > dt.hour:
                    next_hour = h
                    break
            if next_hour is None:
                dt = datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=timezone.utc) + timedelta(days=1)
            else:
                dt = dt.replace(hour=next_hour, minute=0, second=0, microsecond=0)
            continue

        if dt.minute not in minutes:
            next_minute = None
            for m in sorted(minutes):
                if m > dt.minute:
                    next_minute = m
                    break
            if next_minute is None:
                dt = dt.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1)
            else:
                dt = dt.replace(minute=next_minute, second=0, microsecond=0)
            continue

        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

    raise ValueError("No matching timestamp found within search limit")
