def render_table(rows, widths, aligns):
    border = '+' + ''.join('-' * (w + 2) + '+' for w in widths)

    def wrap_cell(text, width):
        words = [w for w in text.split(' ') if w != '']

        if not words:
            return ['']

        lines = []
        current_line = ''

        for word in words:
            if len(word) > width:
                if current_line:
                    lines.append(current_line)
                    current_line = ''
                for i in range(0, len(word), width):
                    lines.append(word[i:i + width])
            else:
                if current_line == '':
                    current_line = word
                elif len(current_line) + 1 + len(word) <= width:
                    current_line = current_line + ' ' + word
                else:
                    lines.append(current_line)
                    current_line = word

        if current_line:
            lines.append(current_line)

        return lines if lines else ['']

    def truncate_lines(lines, width):
        if len(lines) <= 3:
            return list(lines)
        result = list(lines[:3])
        if width >= 3:
            result[2] = result[2][:width - 3] + '...'
        else:
            result[2] = '.' * width
        return result

    def align_text(text, width, align):
        extra = width - len(text)
        if extra <= 0:
            return text
        if align == 'l':
            return text + ' ' * extra
        elif align == 'r':
            return ' ' * extra + text
        else:
            left_pad = extra // 2
            right_pad = extra - left_pad
            return ' ' * left_pad + text + ' ' * right_pad

    def render_row(row):
        cell_lines = []
        for j, cell in enumerate(row):
            w = widths[j]
            lines = wrap_cell(cell, w)
            lines = truncate_lines(lines, w)
            cell_lines.append(lines)

        row_height = max(len(cl) for cl in cell_lines)

        padded = []
        for cl in cell_lines:
            p = list(cl)
            while len(p) < row_height:
                p.append('')
            padded.append(p)

        visual_lines = []
        for i in range(row_height):
            parts = []
            for j in range(len(widths)):
                aligned = align_text(padded[j][i], widths[j], aligns[j])
                parts.append(' ' + aligned + ' ')
            visual_lines.append('|' + '|'.join(parts) + '|')

        return visual_lines

    result_lines = [border]

    for i, row in enumerate(rows):
        if i > 0:
            result_lines.append(border)
        result_lines.extend(render_row(row))

    result_lines.append(border)

    return '\n'.join(result_lines)
