def render_table(rows, widths, aligns):
    def _make_border(widths):
        parts = ['+']
        for w in widths:
            parts.append('-' * (w + 2))
            parts.append('+')
        return ''.join(parts)

    def _wrap_cell(text, width):
        words = [w for w in text.split(' ') if w != '']
        if not words:
            return ['']
        lines = []
        current_line = ''
        for word in words:
            if len(word) > width:
                if current_line:
                    lines.append(current_line)
                    current_line = ''
                pos = 0
                while pos < len(word):
                    lines.append(word[pos:pos + width])
                    pos += width
            else:
                if current_line == '':
                    current_line = word
                elif len(current_line) + 1 + len(word) <= width:
                    current_line = current_line + ' ' + word
                else:
                    lines.append(current_line)
                    current_line = word
        if current_line:
            lines.append(current_line)
        return lines if lines else ['']

    def _truncate_cell(lines, width, max_lines=3):
        if len(lines) <= max_lines:
            return lines
        truncated = lines[:max_lines]
        if width >= 3:
            truncated[2] = truncated[2][:width - 3] + '...'
        else:
            truncated[2] = '.' * width
        return truncated

    def _align_text(text, width, align):
        extra = width - len(text)
        if extra <= 0:
            return text[:width]
        if align == 'l':
            return text + ' ' * extra
        elif align == 'r':
            return ' ' * extra + text
        else:  # 'c'
            left_pad = extra // 2
            right_pad = extra - left_pad
            return ' ' * left_pad + text + ' ' * right_pad

    def _render_row(row, widths, aligns):
        n = len(widths)
        cell_lines = []
        for j in range(n):
            wrapped = _wrap_cell(row[j], widths[j])
            truncated = _truncate_cell(wrapped, widths[j])
            cell_lines.append(truncated)
        row_height = max(len(cl) for cl in cell_lines)
        for j in range(n):
            while len(cell_lines[j]) < row_height:
                cell_lines[j].append('')
        visual_lines = []
        for line_idx in range(row_height):
            parts = ['|']
            for j in range(n):
                aligned = _align_text(cell_lines[j][line_idx], widths[j], aligns[j])
                parts.append(' ')
                parts.append(aligned)
                parts.append(' |')
            visual_lines.append(''.join(parts))
        return visual_lines

    border = _make_border(widths)
    if not rows:
        return border + '\n' + border
    result_lines = [border]
    for i, row in enumerate(rows):
        if i > 0:
            result_lines.append(border)
        result_lines.extend(_render_row(row, widths, aligns))
    result_lines.append(border)
    return '\n'.join(result_lines)
