from bisect import bisect_right


def weighted_interval_schedule(intervals):
    if not intervals:
        return (0, [])

    sorted_intervals = sorted(intervals, key=lambda x: (x[2], x[1], x[0]))
    n = len(sorted_intervals)
    end_times = [iv[2] for iv in sorted_intervals]

    def find_latest_compatible(i):
        start_i = sorted_intervals[i][1]
        return bisect_right(end_times, start_i) - 1

    def schedule_key(weight, chosen):
        starts = tuple(iv[1] for iv in chosen)
        ids = tuple(iv[0] for iv in chosen)
        return (-weight, len(chosen), starts, ids)

    def better(w1, c1, w2, c2):
        return schedule_key(w1, c1) < schedule_key(w2, c2)

    prefix_best = [None] * n

    for i in range(n):
        iv_i = sorted_intervals[i]

        w_solo = iv_i[3]
        c_solo = [iv_i]

        j = find_latest_compatible(i)
        if j >= 0:
            prev_w, prev_chosen = prefix_best[j]
            w_ext = prev_w + iv_i[3]
            c_ext = list(prev_chosen) + [iv_i]
        else:
            w_ext = None
            c_ext = None

        if w_ext is not None and not better(w_solo, c_solo, w_ext, c_ext):
            dp_i = (w_ext, c_ext)
        else:
            dp_i = (w_solo, c_solo)

        if i == 0:
            prefix_best[i] = dp_i
        else:
            prev_best = prefix_best[i - 1]
            if better(dp_i[0], dp_i[1], prev_best[0], prev_best[1]):
                prefix_best[i] = dp_i
            else:
                prefix_best[i] = prev_best

    best_w, best_chosen = prefix_best[n - 1]

    if schedule_key(0, []) < schedule_key(best_w, best_chosen):
        return (0, [])

    return (best_w, [iv[0] for iv in best_chosen])
