def weighted_interval_schedule(intervals):
    """
    Finds the maximum weight set of non-overlapping intervals.

    Args:
        intervals: List of 4-tuples (id, start, end, weight)

    Returns:
        Tuple (best_weight, chosen_ids) where chosen_ids are sorted by (end, start, id)
    """
    if not intervals:
        return (0, [])

    # Create indexed list and sort by end time, then start, then id
    sorted_intervals = sorted(enumerate(intervals), key=lambda x: (x[1][2], x[1][1], x[1][0]))

    n = len(sorted_intervals)

    # dp[i] = (max_weight, chosen_indices, ids_list) for intervals 0..i-1
    dp = [(0, [], [])] * (n + 1)

    for i in range(1, n + 1):
        orig_idx, (current_id, current_start, current_end, current_weight) = sorted_intervals[i - 1]

        # Option 1: Don't include current interval
        weight_without = dp[i - 1][0]
        indices_without = dp[i - 1][1]
        ids_without = dp[i - 1][2]

        # Option 2: Include current interval
        # Find the latest interval that doesn't overlap with current
        prev_compatible_idx = 0
        for j in range(i - 1, 0, -1):
            _, (prev_id, prev_start, prev_end, prev_weight) = sorted_intervals[j - 1]
            if prev_end <= current_start:
                prev_compatible_idx = j
                break

        weight_with = dp[prev_compatible_idx][0] + current_weight
        indices_with = list(dp[prev_compatible_idx][1]) + [i - 1]
        ids_with = list(dp[prev_compatible_idx][2]) + [current_id]

        # Choose based on tie-breaking rules
        choice = _choose_schedule(
            weight_with, indices_with, ids_with,
            weight_without, indices_without, ids_without,
            sorted_intervals
        )
        dp[i] = choice

    best_weight, chosen_indices, chosen_ids = dp[n]

    # Sort chosen_ids by (end, start, id)
    id_to_interval = {interval[0]: interval for _, interval in sorted_intervals}

    sorted_chosen = sorted(
        chosen_ids,
        key=lambda iid: (id_to_interval[iid][2], id_to_interval[iid][1], iid)
    )

    return (best_weight, sorted_chosen)


def _choose_schedule(weight1, indices1, ids1, weight2, indices2, ids2, sorted_intervals):
    """
    Choose between two schedules based on tie-breaking rules.
    Returns (weight, indices, ids) tuple for the chosen schedule.
    """
    # Rule 1: Prefer larger total weight
    if weight1 > weight2:
        return (weight1, indices1, ids1)
    elif weight1 < weight2:
        return (weight2, indices2, ids2)

    # Rule 2: Prefer fewer intervals
    if len(ids1) < len(ids2):
        return (weight1, indices1, ids1)
    elif len(ids1) > len(ids2):
        return (weight2, indices2, ids2)

    # Rules 3 and 4: Compare by start times and ids lexicographically
    id_to_interval = {interval[0]: interval for _, interval in sorted_intervals}

    # Sort both by (end, start, id)
    sorted_ids1 = sorted(ids1, key=lambda iid: (id_to_interval[iid][2], id_to_interval[iid][1], iid))
    sorted_ids2 = sorted(ids2, key=lambda iid: (id_to_interval[iid][2], id_to_interval[iid][1], iid))

    # Rule 3: Compare start times lexicographically
    starts1 = [id_to_interval[iid][1] for iid in sorted_ids1]
    starts2 = [id_to_interval[iid][1] for iid in sorted_ids2]

    if starts1 < starts2:
        return (weight1, indices1, ids1)
    elif starts1 > starts2:
        return (weight2, indices2, ids2)

    # Rule 4: Compare ids lexicographically
    if sorted_ids1 <= sorted_ids2:
        return (weight1, indices1, ids1)
    else:
        return (weight2, indices2, ids2)
